// SLASHER | Dunmoore | frontend modular sem build step
'use strict';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=dt=>new Date(dt).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
const ATTR=[['CIE','Ciências'],['RAL','Raciocínio e Lógica'],['COC','Conhecimento Oculto'],['EDF','Educação Física'],['REF','Reflexo'],['TEC','Oficina e Tecnologia'],['CRI','Criatividade e Estilo'],['SOC','Habilidades Sociais']];
const CLASSES=[['atl','O Atleta','Arrancada','1× por cena, 3 STA para +2 em Escapar.'],['bul','O Bully','Entre eles','1× por cena, Proteger concede +3 Defesa.'],['ner','O Nerd','Padrão oculto','1× por cena, pergunte relação entre duas pistas.'],['pat','A Patricinha','Pessoa certa','1× por sessão, declare contato social plausível.'],['pop','A Popular','Voz firme','1× por cena, conversa segura recupera +5 EST adicionais.'],['reb','O Rebelde','Saída lateral','1× por cena, +2 em REF/TEC com cobertura.'],['par','O Paranormal','Presságio','1× por cena, +5 EST para obter sinal verdadeiro.'],['art','O Artista','Ruído certo','1× por cena, +2 ao criar distração.'],['cod','O Coder','Cópia fria','1× por cena, cópia extra de evidência digital acessível.'],['esc','O Escoteiro','Conheço um caminho','1× por cena, +2 ao localizar rota segura.'],['tra','O Trabalhador','Na gambiarra','1× por cena, +2 em TEC com materiais.'],['pro','O Professor','Contexto histórico','1× por cena, descubra uma conexão documental.']];
const PRESETS={atl:[0,0,0,4,3,0,1,2],bul:[0,0,0,4,2,1,0,3],ner:[2,4,1,0,0,2,1,0],pat:[0,2,0,0,1,0,3,4],pop:[0,1,0,0,2,0,3,4],reb:[0,0,1,2,3,2,2,0],par:[0,2,4,0,1,0,2,1],art:[0,1,1,0,1,1,4,2],cod:[0,3,0,0,1,4,2,0],esc:[1,1,0,3,3,1,0,1],tra:[0,1,0,3,1,4,0,1],pro:[2,4,1,0,0,0,1,2]};
const NAMES=['Eleanor Hayes','Daniel Mercer','Charlotte Reed','Oliver Brooks','Amelia Blackwell','Mason Keller','Hazel Bishop','Isaac Shaw','Vivian Rivers','Caleb Turner','Beth Holloway','Noah Barlow','Grace Sullivan','Elliot Walker','Olivia Keating','Nathan Foster','Leah Whitmore','Finn Abbott','Abigail Quinn','Arthur Pierce','Rachel Dawson','Samuel Graves','Annie Collins','Morgan Hale'];
const OCC=['aluno transferido','voluntária da biblioteca','técnico de eletrônica','fotógrafo amador','garçonete do cais','guarda florestal','aprendiz de mecânico','funcionário do hospital','jornalista do grêmio','professor substituto','atendente de loja de discos','músico de garagem','auxiliar na serraria'];
const HOOKS=['Ouviu três batidas dentro de uma parede vazia.','Tem uma fotografia em que alguém foi apagado.','O nome aparece em um relatório antigo da mina.','Não lembra como conseguiu a chave do hospital.','Sonha com uma coroa sob o lago.','Recebeu uma ligação de uma pessoa desaparecida.','Sabe de um túnel que não consta nos mapas.','Tem medo de descobrir o que o pai assinou.'];
const cls=k=>CLASSES.find(c=>c[0]===k)||CLASSES[0];
const attrObj=k=>Object.fromEntries(ATTR.map(([key],i)=>[key,PRESETS[k]?.[i]??0]));
const uuid=()=>crypto.randomUUID?.()||('id-'+Date.now()+'-'+Math.random().toString(16).slice(2));
const sample=a=>a[Math.floor(Math.random()*a.length)];
const roleIcon=k=>k==='item'?'▣':k==='skill'?'✦':'✝';
const NOCACHE='slasher7-demo-v1';
function toast(msg){const el=$('#toast');if(!el)return;el.textContent=msg;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),4200)}
function safeErr(err){return String(err?.message||err||'Erro inesperado').replace(/invalid login credentials/i,'E-mail ou senha incorretos').replace(/email not confirmed/i,'Confirme seu e-mail para entrar').replace(/user already registered/i,'Este e-mail já está cadastrado')}
function avatar(ch,size=''){return `<div class="avatar ${size}">${ch.portrait?`<img src="${esc(ch.portrait)}" alt="Retrato de ${esc(ch.name)}">`:esc(ch.name?.[0]?.toUpperCase()||'?')}</div>`}
function actorName(id){return state.members.find(m=>m.user_id===id)?.nickname||(id===state.user?.id?'Você':'Sobrevivente')}
const config=window.SLASHER_CONFIG||{};
const ONLINE=!!(config.supabaseUrl?.trim()&&config.supabaseAnonKey?.trim());
const state={mode:ONLINE?'online':'demo',user:null,campaignId:null,campaign:null,campaigns:[],members:[],characters:[],effects:[],rolls:[],audit:[],gmNote:'',page:'lobby',selected:null,modal:null,authTab:'quick',gmPreview:false,loading:false,connection:'offline',channel:null,revision:0};
const isGM=()=>state.campaign&&state.members.some(m=>m.user_id===state.user?.id&&m.role==='gm')&&!state.gmPreview;
const own=ch=>ch?.owner_id===state.user?.id;
const canEdit=ch=>ch&&(isGM()||own(ch));
const selected=()=>state.characters.find(x=>x.id===state.selected)||state.characters[0];
function dateNow(){return new Date().toISOString()}

// ---- Adaptador de demonstração: funcional sem servidor, persistência somente neste navegador ----
class DemoAPI{
 constructor(){this.me={id:'demo-gm',email:'mestre@dunmoore.demo'};this.data=null}
 seed(){const id='dunmoore-1999',now=dateNow();const mk=(key,name,owner,age,occupation)=>{const attrs=attrObj(key),max=12+2*attrs.EDF;return {id:uuid(),campaign_id:id,owner_id:owner,name,class_key:key,age,occupation,attrs,hp:max, hp_max:max,stamina:max,stamina_max:max,stress:0,notes:'',portrait:'',updated_at:now}};
 const chars=[mk('reb','Eleanor Hayes','demo-player',18,'estudante e fotógrafa'),mk('atl','Daniel Mercer','demo-player2',19,'atleta do colégio'),mk('pro','Sr. Wallace',null,54,'professor de história'),mk('par','Margaret Voss',null,37,'arquivista municipal')];
 chars[0].hp=13;chars[0].stress=34;chars[1].hp=8;chars[1].stress=73;
 return {campaigns:[{id,name:'Dunmoore: Ecos da Montanha',invite_code:'DEMO-777',suspicion:2,danger:1,created_at:now}],members:[{campaign_id:id,user_id:'demo-gm',role:'gm',nickname:'Mestre'},{campaign_id:id,user_id:'demo-player',role:'player',nickname:'Eleanor'},{campaign_id:id,user_id:'demo-player2',role:'player',nickname:'Daniel'}],characters:chars,effects:[{id:uuid(),campaign_id:id,character_id:chars[0].id,kind:'item',title:'Lanterna de bolso',details:'Uma pilha ainda funciona.'},{id:uuid(),campaign_id:id,character_id:chars[0].id,kind:'skill',title:'Saída lateral',details:cls('reb')[3]},{id:uuid(),campaign_id:id,character_id:chars[1].id,kind:'condition',title:'Hemorragia',details:'Perde 2 HP por rodada até receber primeiros socorros.'}],rolls:[],audit:[],notes:{[id]:'Uma presença antiga reclama nomes. A escola encobre os registros de 2008. Não revele aos jogadores antes da hora.'}}}
 save(){try{localStorage.setItem(NOCACHE,JSON.stringify(this.data))}catch{ /* armazenamento restrito: sessão em memória */ }}
 async init(){try{this.data=JSON.parse(localStorage.getItem(NOCACHE))||this.seed()}catch{this.data=this.seed()}this.save();return this.me}
 async logout(){return true}
 async listCampaigns(){return this.data.members.filter(m=>m.user_id===this.me.id).map(m=>({...m,campaign:this.data.campaigns.find(c=>c.id===m.campaign_id)}))}
 async createCampaign(n,nick){const id=uuid(),c={id,name:n,invite_code:uuid().replace(/-/g,'').slice(0,12).toUpperCase(),suspicion:0,danger:0,created_at:dateNow()};this.data.campaigns.push(c);this.data.members.push({campaign_id:id,user_id:this.me.id,role:'gm',nickname:nick});this.data.notes[id]='';this.save();return id}
 async joinCampaign(code,nick){const c=this.data.campaigns.find(c=>c.invite_code===code.trim().toUpperCase());if(!c)throw Error('Código não encontrado nesta demonstração. Para jogar com amigos, configure o modo online.');this.data.members.push({campaign_id:c.id,user_id:this.me.id,role:'player',nickname:nick});this.save();return c.id}
 async loadCampaign(id){return {campaign:this.data.campaigns.find(c=>c.id===id),members:this.data.members.filter(m=>m.campaign_id===id),characters:this.data.characters.filter(c=>c.campaign_id===id),effects:this.data.effects.filter(e=>e.campaign_id===id),rolls:this.data.rolls.filter(r=>r.campaign_id===id).slice(-80).reverse(),audit:this.data.audit.filter(a=>a.campaign_id===id).slice(-35).reverse(),gmNote:this.data.notes[id]||''}}
 async createCharacter(p){const attrs=attrObj(p.class_key);const max=12+2*attrs.EDF,id=uuid();this.data.characters.push({id,campaign_id:p.campaign_id,owner_id:p.npc?null:this.me.id,name:p.name,class_key:p.class_key,age:p.age,occupation:p.occupation,attrs,hp:max,hp_max:max,stamina:max,stamina_max:max,stress:0,notes:'',portrait:'',updated_at:dateNow()});this.save();return id}
 audit(message,ch){this.data.audit.push({id:uuid(),campaign_id:state.campaignId,actor_id:this.me.id,character_id:ch,message,created_at:dateNow()})}
 async changeStat(id,key,d){const c=this.data.characters.find(c=>c.id===id);if(!c)throw Error('Ficha não encontrada');c[key]=Math.min(key==='stress'?100:c[key+'_max'],Math.max(0,c[key]+d));this.audit(`Alterou ${key} em ${d}`,id);this.save()}
 async grantEffect(id,kind,title,details){this.data.effects.push({id:uuid(),campaign_id:state.campaignId,character_id:id,kind,title,details,created_at:dateNow()});this.audit(`Concedeu ${kind}: ${title}`,id);this.save()}
 async removeEffect(id){const e=this.data.effects.find(e=>e.id===id);if(!e)return;this.data.effects=this.data.effects.filter(e=>e.id!==id);this.audit(`Removeu ${e.kind}: ${e.title}`,e.character_id);this.save()}
 async setClock(k,v){this.data.campaigns.find(c=>c.id===state.campaignId)[k]=v;this.save()}
 async saveNote(t){this.data.notes[state.campaignId]=t;this.save()}
 async updateCharacter(ch){const c=this.data.characters.find(c=>c.id===ch.id);Object.assign(c,{name:ch.name,notes:ch.notes,portrait:ch.portrait,updated_at:dateNow()});this.save()}
 async assignCharacter(chId,owner){this.data.characters.find(c=>c.id===chId).owner_id=owner;this.audit('Atribuição de ficha alterada',chId);this.save()}
 async roll(p){const natural=p.clientDice?.natural??window.SLASHER_DICE.face(20);const sides=+p.damage_sides||0;const r={id:uuid(),campaign_id:p.campaign_id,actor_id:this.me.id,character_id:p.character_id,kind:p.kind,description:p.description,natural,modifier:p.modifier,total:natural+p.modifier,damage:p.kind==='test'||!sides?0:(p.clientDice?.damage??window.SLASHER_DICE.face(sides)),created_at:dateNow()};this.data.rolls.push(r);this.save();return r}
}
// ---- Adaptador Supabase: RLS, Auth, RPC e Postgres Changes ----
class SupaAPI{
 async init(){const mod=await import('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm');this.sb=mod.createClient(config.supabaseUrl,config.supabaseAnonKey);const {data,error}=await this.sb.auth.getUser();if(error&&!String(error.message).includes('Auth session missing'))console.warn(error);return data?.user||null}
 async auth(kind,email,password){const fn=kind==='register'?'signUp':'signInWithPassword';const {data,error}=await this.sb.auth[fn]({email,password});if(error)throw error;return data}
 async anonymousAuth(nickname){const name=String(nickname||'').trim();if(!/^[\p{L}\p{N} ._-]{2,32}$/u.test(name))throw Error('Nome de usuário inválido (2 a 32 caracteres).');const {data,error}=await this.sb.auth.signInAnonymously({options:{data:{display_name:name}}});if(error)throw error;if(!data?.session||!data.user)throw Error('Ative Anonymous Sign-Ins nas configurações do Supabase.');return data}

 async logout(){const {error}=await this.sb.auth.signOut();if(error)throw error}
 async query(q){const {data,error}=await q;if(error)throw error;return data}
 async rpc(name,args){return this.query(this.sb.rpc('slasher_'+name,args))}
 async listCampaigns(){const a=await this.query(this.sb.from('campaign_members').select('campaign_id,role,nickname,campaigns(*)').eq('user_id',state.user.id).order('joined_at',{ascending:false}));return a.map(m=>({...m,campaign:m.campaigns}))}
 async createCampaign(n,nick){return this.rpc('create_campaign',{p_name:n,p_nickname:nick})}
 async joinCampaign(code,nick){return this.rpc('join_campaign',{p_code:code,p_nickname:nick})}
 async loadCampaign(id){const [campaign,members,characters,effects,rolls,audit,notes]=await Promise.all([
  this.query(this.sb.from('campaigns').select('*').eq('id',id).single()),
  this.query(this.sb.from('campaign_members').select('*').eq('campaign_id',id).order('joined_at')),
  this.query(this.sb.from('characters').select('*').eq('campaign_id',id).order('created_at')),
  this.query(this.sb.from('character_effects').select('*').eq('campaign_id',id).order('created_at')),
  this.query(this.sb.from('rolls').select('*').eq('campaign_id',id).order('created_at',{ascending:false}).limit(80)),
  this.query(this.sb.from('audit_log').select('*').eq('campaign_id',id).order('created_at',{ascending:false}).limit(35)),
  this.query(this.sb.from('gm_notes').select('content').eq('campaign_id',id).maybeSingle())]);
  return {campaign,members,characters,effects,rolls,audit,gmNote:notes?.content||''};}
 async createCharacter(p){return this.rpc('create_character',{p_campaign_id:p.campaign_id,p_name:p.name,p_class:p.class_key,p_age:p.age,p_occupation:p.occupation,p_npc:p.npc})}
 async changeStat(id,key,d){return this.rpc('change_stat',{p_character_id:id,p_stat:key,p_delta:d})}
 async grantEffect(id,kind,title,details){return this.rpc('grant_effect',{p_character_id:id,p_kind:kind,p_title:title,p_details:details})}
 async removeEffect(id){return this.rpc('remove_effect',{p_effect_id:id})}
 async setClock(key,v){return this.rpc('set_clock',{p_campaign_id:state.campaignId,p_clock:key,p_value:v})}
 async saveNote(t){return this.rpc('save_gm_note',{p_campaign_id:state.campaignId,p_text:t})}
 async updateCharacter(ch){return this.rpc('update_character',{p_character_id:ch.id,p_name:ch.name,p_notes:ch.notes,p_portrait:ch.portrait})}
 async assignCharacter(chId,owner){return this.rpc('assign_character',{p_character_id:chId,p_owner:owner||null})}
 async roll(p){
  const standard={p_campaign_id:p.campaign_id,p_character_id:p.character_id||null,p_kind:p.kind,p_description:p.description,p_modifier:p.modifier,p_damage_sides:p.damage_sides||0};
  if(p.clientDice){
    try{return await this.rpc('roll_local',{...standard,p_natural:p.clientDice.natural,p_damage_face:p.clientDice.damage})}
    catch(e){const msg=String(e.message||'');if(/could not find the function|PGRST202|does not exist/i.test(msg))throw Error('A migração dos dados locais ainda não foi executada no Supabase. Abra migrate_dice_local.sql.');throw e}
  }
  return this.rpc('roll',standard)
 }
 subscribe(id,callback){this.unsubscribe();const tables=['campaigns','campaign_members','characters','character_effects','rolls','audit_log','slasher71_monsters','slasher71_inventory','slasher71_shops','slasher71_shop_stock','slasher71_encounters','slasher71_combat_events'];const channel=this.sb.channel('slasher7-'+id);
 for(const table of tables)channel.on('postgres_changes',{event:'*',schema:'public',table,filter:table==='campaigns'?`id=eq.${id}`:`campaign_id=eq.${id}`},()=>callback());
 channel.subscribe(status=>{state.connection=status==='SUBSCRIBED'?'live':status==='CHANNEL_ERROR'?'reconectando':'conectando';updateConnectionStatus()});state.channel=channel;}
 unsubscribe(){if(state.channel){this.sb.removeChannel(state.channel);state.channel=null}}
}
const api=ONLINE?new SupaAPI():new DemoAPI();
// ---- Interface ----
function updateConnectionStatus(){const el=$('#connection');if(el)el.innerHTML=state.mode==='demo'?'<span class="chip red">DEMONSTRAÇÃO LOCAL</span>':`<span class="chip ${state.connection==='live'?'good':'red'}"><span class="live-dot"></span>${esc(state.connection==='live'?'AO VIVO':state.connection.toUpperCase())}</span>`}
function renderLogin(){return `<div class="login-shell"><section class="login-hero"><div class="hero-content"><div class="eyebrow">DUNMOORE / MAINE / ARQUIVO Nº 07</div><div class="hero-line"></div><div class="hero-title">SLASHER</div><div class="hero-sub">Dunmoore</div><p class="lead">Um sistema. Uma mesa conectada. Nenhum lugar seguro. Seus personagens podem ser salvos. A cidade, talvez não.</p><div class="row" style="margin-top:27px"><span class="chip red">SURVIVAL HORROR</span><span class="chip">ARQUIVOS CONECTADOS</span><span class="chip">MULTIPLAYER</span></div></div><div class="hero-foot">EDIÇÃO VII. · O QUE A MONTANHA ENGOLIU AINDA ESTÁ ESCUTANDO.</div></section><section class="login-side"><div class="login-card"><div class="eyebrow">ACESSO RESTRITO / SLASHER NETWORK</div><h2>${state.authTab==='quick'?'Quem entra em Dunmoore?':state.authTab==='register'?'Novo sobrevivente':'Bem-vindo de volta'}</h2><p class="lead">${state.mode==='online'?'Entre com um nome de usuário, sem e-mail e sem senha.':'Ative o modo online no arquivo config.js. Este acesso demonstra a interface usando dados locais.'}</p>
 ${state.mode==='demo'?`<div class="panel stack"><span class="chip red">MODO DEMONSTRAÇÃO</span><p>Você está testando o sistema sem servidor. Os dados ficam somente neste navegador e não são compartilhados com outras pessoas.</p><button class="btn red wide" data-action="demo-enter">Entrar na mesa de demonstração ↗</button><button class="btn flat wide" data-action="demo-reset">Restaurar demonstração</button><a href="manual-6.html" class="btn flat wide">Ler manual de regras 6.0</a></div>`:
 state.authTab==='quick'?`<form id="quick-auth-form"><label class="field">Nome de usuário<input name="nickname" autocomplete="nickname" minlength="2" maxlength="32" required placeholder="Seu nome na mesa"></label><button type="submit" class="btn red wide">Entrar em Dunmoore ↗</button></form><div class="onboarding">Este acesso cria uma sessão única no navegador. Se você sair ou apagar os dados do site, não será possível recuperar as fichas digitando apenas o mesmo nome.</div><button type="button" class="btn flat wide" data-action="auth-tab" data-value="login">Já tenho conta com e-mail</button>`:`<div class="login-switch"><button class="${state.authTab==='login'?'active':''}" data-action="auth-tab" data-value="login">Entrar</button><button class="${state.authTab==='register'?'active':''}" data-action="auth-tab" data-value="register">Criar conta</button></div><form id="auth-form"><label class="field">E-mail<input name="email" type="email" autocomplete="email" required placeholder="voce@email.com"></label><label class="field">Senha<input name="password" type="password" autocomplete="${state.authTab==='register'?'new-password':'current-password'}" required minlength="6" placeholder="Mínimo de 6 caracteres"></label><button class="btn red wide" type="submit">${state.authTab==='register'?'Criar conta':'Acessar campanhas'} ↗</button></form><button type="button" class="btn flat wide" data-action="auth-tab" data-value="quick">← Entrar sem e-mail</button><div class="onboarding">${state.authTab==='register'?'Dependendo da configuração do Supabase, você receberá um e-mail de confirmação.':'Use seu e-mail cadastrado. Cada pessoa recebe permissões próprias na campanha.'}</div>`}
 </div></section></div>`}
const navItems=[['mesa','◈','Mesa Atual'],['dashboard','▦','Visão geral'],['characters','♟','Sobreviventes'],['sheet','▤','Ficha digital'],['dice','⬡','Rolagens'],['gm','✝','Painel do mestre'],['rules','☷','Regras rápidas']];
function renderShell(content){return `<div class="shell"><aside class="sidebar"><div class="brand"><div class="wordmark">SLASHER</div><small>DUNMOORE, MAINE</small></div><div class="side-group-label">ARQUIVOS DA CAMPANHA</div><nav class="side-nav" aria-label="Navegação"><button data-action="go" data-value="lobby" class="${state.page==='lobby'?'active':''}">⌂ Campanhas</button>${state.campaign?navItems.filter(([id])=>id!=='gm'||isGM()).map(([id,icon,title])=>`<button data-action="go" data-value="${id}" class="${state.page===id?'active':''}">${icon} ${title}</button>`).join(''):''}</nav><div class="side-foot"><div class="eyebrow">STATUS DO ARQUIVO</div><p class="tiny" style="margin:8px 0">A cidade nunca esquece. Ela apenas muda os registros.</p><span class="edition-footnote">edição vii. · experimental</span></div></aside><div class="main"><header class="topbar"><div><div class="eyebrow">${state.campaign?'CAMPANHA ATIVA':'ARQUIVO CENTRAL'}</div><b>${esc(state.campaign?.name||'Dunmoore Horror Story')}</b></div><div class="topbar-right"><span id="connection">${state.mode==='demo'?'<span class="chip red">DEMO LOCAL</span>':'<span class="chip">CONECTANDO</span>'}</span><span class="user-email tiny muted">${esc(state.user?.user_metadata?.display_name||state.user?.email||'Mestre de teste')}</span>${state.mode==='demo'?`<button class="btn small flat" data-action="switch-role">${state.gmPreview?'Visão do mestre':'Visualizar como jogador'}</button>`:`<button class="btn small flat" data-action="logout">Sair</button>`}</div></header><main class="main-body">${content}</main></div></div>`}
function titleBlock(k,title,desc,actions=''){return `<header class="section-head"><div><div class="eyebrow">${k}</div><h2>${title}</h2><p>${desc}</p></div>${actions?`<div class="row">${actions}</div>`:''}</header>`}
function rosterCard(ch,action='select-char'){const pc=Math.round(ch.hp/ch.hp_max*100);return `<button class="survivor-card ${state.selected===ch.id?'active':''}" data-action="${action}" data-id="${ch.id}">${avatar(ch)}<div class="info"><b>${esc(ch.name)}</b><small>${esc(cls(ch.class_key)[1])} · ${ch.owner_id?'Jogador':'NPC'}</small><div class="meter"><span style="width:${pc}%"></span></div><small class="mono">HP ${ch.hp}/${ch.hp_max} · EST ${ch.stress}</small></div><span class="accent">↗</span></button>`}
function renderLobby(){const items=state.campaigns.map(m=>`<button class="survivor-card" data-action="open-campaign" data-id="${m.campaign_id}"><div class="avatar" style="font:30px Georgia">⌂</div><div class="info"><b>${esc(m.campaign?.name||'Campanha')}</b><small>${m.role==='gm'?'MESTRE':'JOGADOR'} · ${esc(m.nickname)}</small><small class="mono">${esc(m.campaign?.invite_code||'')}</small></div><span class="accent">↗</span></button>`).join('');return `${titleBlock('SLASHER NETWORK / ARQUIVOS','Suas campanhas','Crie uma mesa de horror ou entre numa investigação existente.')}<section class="hero-panel"><div><div class="eyebrow">DUNMOORE / MESA CONECTADA</div><h2>Dunmoore continua esperando.</h2><p>Acesse as fichas, distribua itens e conduza uma campanha com seus jogadores conectados.</p><div class="row" style="margin-top:22px"><button class="btn red" data-action="modal" data-value="create-campaign">+ Criar campanha</button><button class="btn flat" data-action="modal" data-value="join-campaign">Entrar com convite</button></div></div></section><div class="panel"><div class="panel-title"><h3>Arquivos disponíveis</h3><span class="tag">${state.campaigns.length} CAMPANHAS</span></div><div class="grid2">${items||'<div class="empty full"><b>Nenhuma campanha encontrada</b>Crie uma campanha para assumir o papel de mestre.</div>'}</div>${state.mode==='demo'?'<p class="hint" style="margin-top:14px">Esta demonstração não conecta pessoas de outros dispositivos. Para uma mesa de verdade, siga o guia de instalação do kit.</p>':''}</div>`}
function renderDashboard(){const c=state.campaign,pcs=state.characters.filter(x=>x.owner_id), npcs=state.characters.filter(x=>!x.owner_id);return `${titleBlock('DUNMOORE / SALA DE COMANDO','Sua mesa está aberta',`${state.members.length} participante(s) no arquivo · mudanças ${state.mode==='demo'?'salvas localmente':'sincronizadas'}.`,isGM()?`<button class="btn red" data-action="modal" data-value="create-character">+ Novo sobrevivente</button><button class="btn flat" data-action="random-npc">Gerar NPC</button>`:`<button class="btn red" data-action="modal" data-value="create-character">+ Criar personagem</button>`)}<section class="hero-panel"><div><div class="eyebrow">ASHES TO ASHES / DUNMOORE 2025</div><h2>Não responda às três batidas.</h2><p>Você não precisa derrotar a criatura. Precisa sobreviver à próxima rodada e descobrir por que ela conhece seu nome.</p><div class="row" style="margin-top:17px"><button class="btn soft" data-action="go" data-value="dice">⬡ Rolar D20</button><button class="btn flat" data-action="go" data-value="characters">Ver fichas</button></div></div></section><div class="grid4" style="margin-bottom:18px"><div class="metric"><strong>${pcs.length}</strong><p>Personagens</p></div><div class="metric"><strong>${npcs.length}</strong><p>NPCs no arquivo</p></div><div class="metric"><strong>${state.members.length}</strong><p>Participantes</p></div><div class="metric"><strong>${state.rolls.length}</strong><p>Rolagens recentes</p></div></div><div class="grid2"><div class="panel"><div class="panel-title"><h3>Sobreviventes</h3><button class="btn ghost small" data-action="go" data-value="characters">Todos ↗</button></div><div class="stack">${state.characters.slice(0,5).map(c=>rosterCard(c)).join('')||'<div class="empty">Nenhum personagem ainda.</div>'}</div></div><div class="panel"><div class="panel-title"><h3>Últimas ocorrências</h3><button class="btn ghost small" data-action="go" data-value="dice">Registro ↗</button></div>${renderRollList(5)}<hr class="sep"><h3 style="font-size:18px;margin-bottom:12px">Convite da mesa</h3>${isGM()?`<div class="invite"><div class="eyebrow">CÓDIGO DE ACESSO</div><div class="mono" style="margin:7px 0">${esc(c.invite_code)}</div><button class="btn small flat" data-action="copy-invite">Copiar código</button></div>`:'<p class="muted">Peça ao mestre o código para adicionar outros jogadores.</p>'}</div></div>`}
function renderCharacters(){return `${titleBlock('ARQUIVO PESSOAL / SOBREVIVENTES','Pessoas que ainda respiram','Ficha rápida de cada sobrevivente e NPC da campanha.',`<button class="btn red" data-action="modal" data-value="create-character">+ Criar ficha</button>${isGM()?'<button class="btn flat" data-action="random-npc">⚄ NPC aleatório</button>':''}`)}<div class="grid2">${state.characters.map(ch=>rosterCard(ch)).join('')||'<div class="empty full"><b>O arquivo está vazio.</b>Comece criando um personagem.</div>'}</div>${isGM()?`<div class="panel" style="margin-top:21px"><div class="panel-title"><h3>Participantes e permissões</h3><span class="tag">${state.members.length} MEMBROS</span></div><div class="grid2">${state.members.map(m=>`<div class="between" style="border-bottom:1px solid var(--line);padding:9px 0"><div><b>${esc(m.nickname)}</b><p class="role-name">${m.role==='gm'?'Mestre':'Jogador'}</p></div><span class="chip">${state.characters.filter(ch=>ch.owner_id===m.user_id).length} fichas</span></div>`).join('')}</div></div>`:''}`}
function statBox(label,v,max,key){return `<div class="kpi"><div class="between"><span class="stat-label">${label}</span><span class="stat-label mono">${v}/${max}</span></div><div class="stat-value">${v}</div><div class="meter ${key}"><span style="width:${Math.max(0,Math.min(100,v/max*100))}%"></span></div></div>`}
function effectGroup(ch,kind,label){let entries=state.effects.filter(x=>x.character_id===ch.id&&x.kind===kind);return `<div class="panel"><div class="panel-title"><h3>${label}</h3><span class="tag">${entries.length}</span></div><div class="item-list">${entries.map(e=>`<div class="item"><div><strong><span class="accent">${roleIcon(kind)}</span> ${esc(e.title)}</strong><small>${esc(e.details||'Nenhuma descrição')}</small></div>${isGM()?`<button class="btn small negative" data-action="remove-effect" data-id="${e.id}" title="Retirar recurso">Remover</button>`:`<span class="chip">${kind==='item'?'EQUIP.':kind==='skill'?'TALENTO':'ESTADO'}</span>`}</div>`).join('')||`<div class="hint">${kind==='item'?'Nenhum item registrado.':kind==='skill'?'Nenhuma habilidade concedida.':'Nenhuma condição ativa.'}</div>`}</div>${isGM()?`<button class="btn small flat" style="margin-top:12px" data-action="modal" data-value="grant" data-kind="${kind}" data-id="${ch.id}">+ Adicionar ${kind==='item'?'item':kind==='skill'?'habilidade':'condição'}</button>`:''}</div>`}
function renderSheet(){const ch=selected();if(!ch)return `${titleBlock('FICHA / ARQUIVO DO SOBREVIVENTE','Sobrevivente','Escolha um personagem para começar.')}<div class="empty">Nenhum personagem criado.<div style="margin-top:15px"><button class="btn red" data-action="modal" data-value="create-character">Criar ficha</button></div></div>`;
const powers=cls(ch.class_key);const can=canEdit(ch);const editable=can?`<button class="btn small flat" data-action="modal" data-value="edit-character" data-id="${ch.id}">Editar retrato e anotações</button>`:'';
return `${titleBlock('REGISTRO / DUNMOORE','Ficha do sobrevivente','Pessoas desaparecem; suas fichas permanecem.',`<select aria-label="Escolher personagem" id="sheet-picker" style="width:auto;min-width:180px">${state.characters.map(x=>`<option value="${x.id}" ${x.id===ch.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`)}<div class="sheet-layout"><div class="stack"><div class="panel profile-panel">${avatar(ch,'large')}<div class="name">${esc(ch.name)}</div><p class="eyebrow" style="margin:8px 0">${esc(powers[1])} • ${ch.age} ANOS</p><p class="muted tiny">${esc(ch.occupation||'Ocupação não registrada')}</p><p class="tiny" style="margin:10px 0">${ch.owner_id?`Ficha de ${esc(actorName(ch.owner_id))}`:'NPC / Controle do mestre'}</p>${editable}<div class="row" style="justify-content:center;margin-top:10px">${isGM()?`<button class="btn small flat" data-action="modal" data-value="assign" data-id="${ch.id}">Atribuir jogador</button>`:''}</div></div><div class="panel"><div class="eyebrow">PODER DO ARQUÉTIPO</div><h3 style="margin:8px 0">${esc(powers[2])}</h3><p class="hint">${esc(powers[3])}</p></div><div class="panel"><div class="panel-title"><h3>Diário pessoal</h3></div><p class="hint" style="white-space:pre-wrap">${esc(ch.notes||'Nenhum registro. As coisas esquecidas costumam voltar.')}</p></div></div><div class="stack"><div class="panel"><div class="panel-title"><h3>Condição física</h3><span class="chip ${ch.hp<=0?'red':'good'}">${ch.hp<=0?'INCAPACITADO':ch.hp<=Math.floor(ch.hp_max/2)?'FERIDO':'VIVO'}</span></div><div class="grid3">${statBox('HP',ch.hp,ch.hp_max,'hp')}${statBox('STAMINA',ch.stamina,ch.stamina_max,'sta')}${statBox('ESTRESSE',ch.stress,100,'stress')}</div></div><div class="panel"><div class="panel-title"><h3>Atributos</h3><span class="tag">10 PONTOS</span></div><div class="attribute-grid">${ATTR.map(([k,name])=>`<div class="attr" title="${esc(name)}"><small>${k}</small><div class="number">${Number(ch.attrs[k]||0)}</div></div>`).join('')}</div><p class="hint" style="margin-top:13px">Teste: 1d20 + atributo + circunstância • DTs: 8 / 12 / 16 / 20.</p><button class="btn red" style="margin-top:12px" data-action="go" data-value="dice">⬡ Rolar um teste</button></div><div class="grid2">${effectGroup(ch,'item','Inventário')}${effectGroup(ch,'skill','Habilidades')}</div>${effectGroup(ch,'condition','Ferimentos e condições')}</div></div>`}
function rollDescription(kind,attribute,characterName){const suffix=characterName?' · '+characterName:'';if(kind==='monster')return 'Ataque de criatura';if(kind==='attack')return 'Ataque de sobrevivente'+suffix;const a=ATTR.find(([key])=>key===attribute);return (a?'Teste de '+a[1]+' ('+a[0]+')':'Teste geral (sem atributo)')+suffix}
function renderRollList(limit=30){const list=state.rolls.slice(0,limit);return `<div class="journal">${list.map(r=>`<div class="journal-event"><div class="between"><b>${r.kind==='monster'?'☠ ':r.kind==='attack'?'⚔ ':'⬡ '}${esc(r.description||'Teste de habilidade')}</b><small>${fmt(r.created_at)}</small></div><p>${esc(actorName(r.actor_id))} · D20 <b class="accent">${r.natural}</b> ${r.modifier<0?'−':'+'} ${Math.abs(r.modifier)} = <b style="color:white">${r.total}</b>${r.damage?' · dano '+r.damage:''}</p></div>`).join('')||'<div class="empty"><b>Silêncio total.</b>Nenhuma rolagem registrada ainda.</div>'}</div>`}
function renderDice(){const choices=state.characters.filter(ch=>own(ch)||isGM());const ch=selected();const def=choices.find(c=>c.id===ch?.id)||choices[0];return `${titleBlock('ARQUIVO DE COMBATE / D20','Rolagens de dados','Resultado animado, registrado e compartilhado com a mesa.')}<div class="grid2"><div class="panel"><div class="panel-title"><h3>Executar rolagem</h3><span class="chip red">1D20</span></div><form id="dice-form"><label class="field">Quem está rolando<select name="character_id"><option value="">Sem personagem</option>${choices.map(c=>`<option value="${c.id}" ${c.id===def?.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label class="field">Tipo de rolagem<select name="kind" id="dice-kind"><option value="test">Teste de atributo</option><option value="attack">Ataque de sobrevivente</option>${isGM()?'<option value="monster">Ataque de criatura</option>':''}</select></label><label class="field">Descrição<input name="description" maxlength="160" placeholder="Ex.: fugir do Escavado, atacar com canivete"></label><div class="field-row"><label class="field">Atributo<select name="attribute" id="dice-attr"><option value="none">Sem atributo</option>${ATTR.map(([k,n])=>`<option value="${k}">${k} · ${esc(n)}</option>`).join('')}</select></label><label class="field">Circunstância<select name="circumstance">${[-4,-3,-2,-1,0,1,2,3,4].map(n=>`<option value="${n}" ${n===0?'selected':''}>${n>0?'+':''}${n}</option>`).join('')}</select></label></div><label class="field">Dado de dano (para ataques)<select name="damage_sides"><option value="0">Sem dado</option><option value="4">1d4</option><option value="6" selected>1d6</option><option value="8">1d8</option><option value="10">1d10</option><option value="12">1d12</option></select></label><p class="hint" style="margin:10px 0 16px">O servidor calcula o D20 no modo online. O dano só é aplicado à ficha quando o mestre o confirma.</p><button type="submit" class="btn red wide">⬡ ROLAR D20</button></form></div><div class="panel"><div class="panel-title"><h3>Registro da mesa</h3><span class="tag">TEMPO REAL</span></div>${renderRollList(25)}</div></div>`}
function clockRender(key,title,max,desc){const val=Number(state.campaign?.[key]||0);return `<div class="panel"><div class="between"><div><div class="eyebrow">${title}</div><h3>${val} / ${max}</h3></div><span class="tag">MESTRE</span></div><p class="hint">${desc}</p><div class="clock">${Array.from({length:max},(_,i)=>`<button class="${val>i?'filled':''}" data-action="set-clock" data-key="${key}" data-value="${i+1}" title="Definir ${i+1}">${val>i?'✕':'·'}</button>`).join('')}</div><button class="btn small flat" data-action="set-clock" data-key="${key}" data-value="0">Zerar relógio</button></div>`}
function renderGm(){if(!isGM())return '<div class="empty">Apenas o mestre pode entrar neste arquivo.</div>';const ch=selected();return `${titleBlock('MESTRE / ARQUIVO CONFIDENCIAL','O narrador não esquece.','Controle os recursos, eventos e estados de todos os sobreviventes.',`<button class="btn red" data-action="random-npc">⚄ Criar NPC aleatório</button><button class="btn flat" data-action="modal" data-value="create-character">+ Criar ficha</button>`)}<div class="grid2" style="margin-bottom:16px">${clockRender('suspicion','SUSPEITA DA CIDADE',6,'O quanto Dunmoore suspeita da investigação.')}${clockRender('danger','PERIGO DO LOCAL',4,'A ameaça cresce quando a investigação faz barulho.')}</div><div class="gm-grid"><div class="panel"><div class="panel-title"><h3>Ficha sob controle</h3><span class="chip red">PAINEL DO MESTRE</span></div><label class="field">Sobrevivente<select id="gm-picker">${state.characters.map(c=>`<option value="${c.id}" ${c.id===ch?.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>${ch?`<div class="row" style="margin-bottom:13px">${avatar(ch)}<div><b>${esc(ch.name)}</b><p class="tiny muted">${esc(cls(ch.class_key)[1])}</p></div></div>${[['hp','HP',ch.hp,ch.hp_max],['stamina','STA',ch.stamina,ch.stamina_max],['stress','EST',ch.stress,100]].map(([k,label,n,max])=>`<div class="between" style="margin:11px 0"><div><div class="eyebrow">${label}</div><b class="mono">${n} / ${max}</b></div><div class="counter-control"><button class="btn small flat" data-action="stat" data-id="${ch.id}" data-stat="${k}" data-delta="-5">−5</button><button class="btn small flat" data-action="stat" data-id="${ch.id}" data-stat="${k}" data-delta="-1">−1</button><button class="btn small soft" data-action="stat" data-id="${ch.id}" data-stat="${k}" data-delta="1">+1</button><button class="btn small soft" data-action="stat" data-id="${ch.id}" data-stat="${k}" data-delta="5">+5</button></div></div>`).join('')}<hr class="sep"><div class="row"><button class="btn red" data-action="modal" data-value="grant" data-id="${ch.id}" data-kind="item">+ Item</button><button class="btn flat" data-action="modal" data-value="grant" data-id="${ch.id}" data-kind="skill">+ Habilidade</button><button class="btn flat" data-action="modal" data-value="grant" data-id="${ch.id}" data-kind="condition">+ Condição</button></div>`:'<p class="hint">Crie uma ficha para acessar os controles.</p>'}</div><div class="stack"><div class="panel"><div class="panel-title"><h3>Notas secretas</h3><span class="chip red">INVISÍVEL AOS JOGADORES</span></div><label class="field">Plano, pistas e informações ocultas<textarea id="gm-note" rows="6" maxlength="20000" placeholder="Somente o mestre vê este texto">${esc(state.gmNote)}</textarea></label><button class="btn red" data-action="save-gm-note">Salvar segredo</button></div><div class="panel"><div class="panel-title"><h3>Registro administrativo</h3></div><div class="journal">${state.audit.slice(0,12).map(a=>`<div class="journal-event"><b>${esc(a.message)}</b><p>${esc(actorName(a.actor_id))} · ${fmt(a.created_at)}</p></div>`).join('')||'<p class="hint">Nenhuma ação do mestre registrada.</p>'}</div></div></div></div><div class="panel" style="margin-top:16px"><div class="panel-title"><h3>Código de convite</h3></div><div class="invite"><div class="eyebrow">CONVITE DE CAMPANHA</div><div class="mono">${esc(state.campaign.invite_code)}</div><div class="row" style="margin-top:12px"><button class="btn small flat" data-action="copy-invite">Copiar convite</button><span class="hint">Envie aos jogadores que possuem uma conta.</span></div></div></div>`}
function renderRules(){const rules=[['TESTES','1d20 + atributo (0–4) + circunstância (até ±4). DT 8 fácil; 12 normal; 16 difícil; 20 extremo. Falha por 1 a 3 pode obter sucesso com custo.'],['VIDA E MORTE','HP máximo = 12 + (2×EDF). Um golpe de 6+ dano ou crítico gera ferimento grave. A 0 HP o personagem fica incapacitado.'],['HEMORRAGIA','Hemorragia grave: perde 2 HP por rodada até receber socorro. Primeiros socorros exigem recursos e oportunidade, não são magia de cura.'],['STAMINA','STA máxima = 12 + (2×EDF). Esquiva custa 3 STA. Descansos seguros recuperam STA, mas não apagam ferimentos graves.'],['ESTRESSE','Estresse de 0 a 100. O medo impõe escolhas e consequências, não perda automática da agência do jogador.'],['ATAQUE DO PREDADOR','A criatura anuncia intenção antes de executar a ameaça. Investigar, bloquear acesso e fugir costuma ser melhor que enfrentar.'],['INVESTIGAÇÃO','Pistas essenciais não exigem rolagem. Dados decidem tempo, discrição e custos. Não trave a história por uma falha.'],['RECUPERAÇÃO','Feridas persistem e precisam de cuidados e dias. A sobrevivência deve ter consequências além da cena.']];return `${titleBlock('REGRAS / COMPATÍVEL COM A EDIÇÃO VI','A lei da sobrevivência','A edição VII adiciona multiplayer e administração online. O núcleo de regras permanece o da edição VI.',`<a class="btn red" href="manual-6.html" target="_blank" rel="noopener">Abrir manual completo ↗</a>`)}<div class="rules-grid">${rules.map(([a,b])=>`<div class="rule-section"><div class="eyebrow">PROTOCOLO ${a}</div><h3>${a}</h3><p>${b}</p></div>`).join('')}</div>`}
function renderModal(){if(!state.modal)return '';const m=state.modal;let body='';if(m.type==='create-campaign')body=`<h2>Criar campanha</h2><p class="lead">Você será o mestre. Um convite será gerado automaticamente.</p><form id="create-campaign"><label class="field">Nome da campanha<input name="name" required minlength="3" maxlength="90" placeholder="Ex.: Dunmoore: O Último Ano"></label><label class="field">Seu nome na mesa<input name="nick" required minlength="2" maxlength="50" placeholder="Ex.: Narrador" value="${esc(state.user?.user_metadata?.display_name||'')}"></label><div class="modal-footer"><button type="button" class="btn flat" data-action="close-modal">Cancelar</button><button type="submit" class="btn red">Criar mesa</button></div></form>`;
 if(m.type==='join-campaign')body=`<h2>Entrar na campanha</h2><p class="lead">Peça o código de acesso ao mestre.</p><form id="join-campaign"><label class="field">Código de convite<input name="code" required placeholder="CÓDIGO DA MESA" style="text-transform:uppercase" autocomplete="off"></label><label class="field">Seu nome na mesa<input name="nick" required minlength="2" maxlength="50" placeholder="Seu apelido" value="${esc(state.user?.user_metadata?.display_name||'')}"></label><div class="modal-footer"><button type="button" class="btn flat" data-action="close-modal">Cancelar</button><button type="submit" class="btn red">Entrar</button></div></form>`;
 if(m.type==='create-character'){let npc=isGM();body=`<h2>Novo sobrevivente</h2><p class="lead">Escolha uma classe com 10 pontos pré-definidos. Crie sua ficha ou um NPC para o arquivo.</p><form id="create-character"><div class="field-row"><label class="field">Nome<input name="name" required minlength="2" maxlength="90" value="${esc(m.random?.name||'')}" placeholder="Nome e sobrenome"></label><label class="field">Idade<input name="age" type="number" min="10" max="100" value="${m.random?.age||18}" required></label></div><label class="field">Classe<select name="class_key" id="class-picker">${CLASSES.map(c=>`<option value="${c[0]}" ${(m.random?.class_key||'ner')===c[0]?'selected':''}>${esc(c[1])}</option>`).join('')}</select></label><div id="class-preview" class="preview">${classSummary(m.random?.class_key||'ner')}</div><label class="field">Ocupação<input name="occupation" maxlength="120" value="${esc(m.random?.occupation||'')}" placeholder="Estudante, técnico, arquivista..."></label>${npc?`<label style="display:flex;align-items:center;gap:9px;margin:13px 0"><input type="checkbox" name="npc" checked style="width:19px;min-height:19px">Criar como NPC sem dono</label>`:''}<div class="row"><button type="button" class="btn flat small" data-action="random-fields">⚄ Preencher aleatoriamente</button></div><div class="modal-footer"><button type="button" class="btn flat" data-action="close-modal">Cancelar</button><button type="submit" class="btn red">Salvar sobrevivente</button></div></form>`}
 if(m.type==='grant'){const kind=m.kind||'item';body=`<h2>Conceder ${kind==='skill'?'habilidade':kind==='condition'?'condição':'item'}</h2><p class="lead">O recurso aparecerá na ficha selecionada dos jogadores conectados.</p><form id="grant-effect"><input name="character_id" type="hidden" value="${esc(m.id)}"><input name="kind" type="hidden" value="${esc(kind)}"><label class="field">Nome do recurso<input name="title" maxlength="80" minlength="2" required placeholder="Ex.: Chave da Ala Norte"></label><label class="field">Descrição<textarea name="details" maxlength="500" placeholder="Efeito e informações do recurso"></textarea></label><div class="modal-footer"><button type="button" class="btn flat" data-action="close-modal">Cancelar</button><button type="submit" class="btn red">Conceder à ficha</button></div></form>`}
 if(m.type==='edit-character'){const ch=state.characters.find(c=>c.id===m.id);if(ch){body=`<h2>Editar sobrevivente</h2><p class="lead">O retrato ficará salvo na ficha e sincronizado com os membros da campanha.</p><form id="edit-character"><input type="hidden" name="id" value="${ch.id}"><label class="field">Nome<input name="name" value="${esc(ch.name)}" maxlength="90" minlength="2" required></label><label class="field">Retrato (JPG, PNG ou WebP; até 8 MB)<input id="portrait-file" type="file" accept="image/jpeg,image/png,image/webp"></label><div class="row"><div id="portrait-preview">${avatar(ch)}</div><button type="button" class="btn flat small" data-action="clear-portrait">Remover retrato</button></div><label class="field" style="margin-top:12px">Anotações do personagem (visíveis aos membros da mesa)<textarea name="notes" maxlength="5000" rows="5">${esc(ch.notes)}</textarea></label><div class="modal-footer"><button type="button" class="btn flat" data-action="close-modal">Cancelar</button><button type="submit" class="btn red">Salvar ficha</button></div></form>`}}
 if(m.type==='assign'){const ch=state.characters.find(c=>c.id===m.id);body=`<h2>Atribuir personagem</h2><p class="lead">Mude o dono da ficha de ${esc(ch?.name||'sobrevivente')} sem perder recursos e ferimentos.</p><form id="assign-character"><input name="id" type="hidden" value="${m.id}"><label class="field">Novo responsável<select name="owner_id"><option value="">NPC sem dono</option>${state.members.map(x=>`<option value="${x.user_id}" ${ch?.owner_id===x.user_id?'selected':''}>${esc(x.nickname)} (${x.role==='gm'?'mestre':'jogador'})</option>`).join('')}</select></label><div class="modal-footer"><button class="btn flat" type="button" data-action="close-modal">Cancelar</button><button class="btn red" type="submit">Confirmar</button></div></form>`}
 return `<div class="modal-backdrop" role="presentation" id="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="SLASHER: ${esc(m.type)}">${body}</section></div>`}
function classSummary(key){const a=PRESETS[key]||PRESETS.ner,p=cls(key);return `<div class="eyebrow">ATRIBUTOS PRÉ-DEFINIDOS · 10 PONTOS</div><div class="row" style="margin-top:9px">${ATTR.map(([k],i)=>`<span class="tag">${k} <b style="color:white">${a[i]}</b></span>`).join('')}</div><p class="hint" style="margin-top:9px"><b>${esc(p[2])}:</b> ${esc(p[3])} · HP/STA ${12+2*a[3]}</p>`}
function renderDiceOverlay(r,rolling=false){return `<div class="dice-shade" id="dice-overlay"><div class="dice-dialog"><div class="eyebrow">SLASHER / PROTOCOLO DE ROLAGEM</div><h2>${rolling?'O dado está girando...':'Resultado da rolagem'}</h2><div class="dice-box ${rolling?'roll':''}" id="dice-face">${rolling?'?':r.natural}</div>${rolling?`<p class="muted">O destino ainda não escolheu um número.</p>`:`<p class="result-total">${r.total}<span class="tiny muted"> total</span></p><p class="muted">D20 natural ${r.natural} ${r.modifier>=0?'+':'−'} ${Math.abs(r.modifier)} · ${esc(r.description||'Rolagem')}</p>${r.damage?`<p class="result-damage">Dano potencial: ${r.damage}</p>`:''}<button class="btn red wide" data-action="close-dice" style="margin-top:18px">Fechar resultado</button>`}</div></div>`}
function render(){const root=$('#app');if(!state.user){root.innerHTML=renderLogin();return}let page=state.page;if(!state.campaign)page='lobby';const components={lobby:renderLobby,mesa:()=>window.SLASHER71.render(state),dashboard:renderDashboard,characters:renderCharacters,sheet:renderSheet,dice:renderDice,gm:renderGm,rules:renderRules};root.innerHTML=renderShell((components[page]||renderLobby)())+renderModal();updateConnectionStatus();state._mesaRender=render;if(page==='mesa')window.SLASHER71.attachDrag(state)}
// ---- Fluxos da mesa e interações ----
async function loadLobby(){state.campaigns=await api.listCampaigns();state.campaign=null;state.campaignId=null;state.characters=[];state.effects=[];state.selected=null;state.page='lobby';if(api.unsubscribe)api.unsubscribe();render()}
async function openCampaign(id){if(api.unsubscribe)api.unsubscribe();state.campaignId=id;state.page='mesa';await refreshCampaign(true);if(api.subscribe)api.subscribe(id,()=>{clearTimeout(syncTimer);syncTimer=setTimeout(()=>refreshCampaign(false).catch(e=>console.error(e)),300)})}
let syncTimer=null,refreshing=false;
async function refreshCampaign(force=false){if(!state.campaignId||refreshing)return;refreshing=true;try{const payload=await api.loadCampaign(state.campaignId);if(!payload?.campaign)throw Error('Campanha não encontrada ou acesso revogado');Object.assign(state,payload);await window.SLASHER71.load(state,api);if(!state.characters.some(c=>c.id===state.selected))state.selected=state.characters[0]?.id||null;
 const editing=!force&&(state.modal||document.activeElement?.closest('form')||document.activeElement?.id==='gm-note');if(!editing)render();else updateConnectionStatus();}finally{refreshing=false}}
async function syncAction(cb,notice='Alteração salva e sincronizada.'){try{await cb();if(state.campaignId)await refreshCampaign(true);else await loadLobby();if(notice)toast(notice)}catch(e){console.error(e);toast('Erro: '+safeErr(e))}}
function randomChar(){return {name:sample(NAMES),class_key:sample(CLASSES)[0],age:16+Math.floor(Math.random()*35),occupation:sample(OCC),hook:sample(HOOKS)}}
async function randomNpc(){if(!isGM())throw Error('Somente o mestre pode criar NPCs');const info=randomChar(),id=await api.createCharacter({campaign_id:state.campaignId,name:info.name,class_key:info.class_key,age:info.age,occupation:info.occupation,npc:true});const note=state.gmNote+(state.gmNote?'\n\n':'')+`NPC: ${info.name}\nSegredo: ${info.hook}`;await api.saveNote(note);state.selected=id;await refreshCampaign(true);toast(`NPC ${info.name} criado. Seu segredo está no caderno do mestre.`)}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('Copiado para a área de transferência.')}catch{window.prompt('Copie o código de convite:',text)}}
function openDiceOverlay(r){$('#dice-overlay')?.remove();document.body.insertAdjacentHTML('beforeend',renderDiceOverlay(r))}
function executeRoll(p){
 if($('#dice-overlay'))return;
 const local=window.SLASHER_DICE.build(p);
 const optimistic={...p,...local,description:p.description,created_at:new Date().toISOString(),id:'local-'+Date.now()};
 document.body.insertAdjacentHTML('beforeend',renderDiceOverlay(null,true));
 const face=$('#dice-face');let n=1;
 const spin=setInterval(()=>{if(face?.isConnected)face.textContent=String(n++%20+1)},50);
 let statusText='⟳ Sincronizando com a mesa...',failed=false;
 const status=()=>{const el=$('#dice-sync-note');if(el){el.textContent=statusText;el.classList.toggle('error',failed)}};
 const sync=api.roll({...p,clientDice:local}).then(saved=>{
   statusText='✓ Resultado registrado na mesa';
   if(state.campaignId===p.campaign_id){state.rolls=[saved,...state.rolls.filter(r=>r.id!==saved.id)].slice(0,80)}
   status();return saved;
 }).catch(e=>{
   failed=true;statusText='⚠ Não sincronizado. A rolagem não entrou no histórico.';
   status();console.error('Falha ao sincronizar D20:',e);toast('Rolagem não registrada: '+safeErr(e));return null;
 });
 setTimeout(()=>{
  clearInterval(spin);
  if(!$('#dice-overlay'))return;
  openDiceOverlay(optimistic);
  const dialog=$('#dice-overlay .dice-dialog');if(dialog)dialog.insertAdjacentHTML('beforeend','<p class="dice-sync-note" id="dice-sync-note"></p>');
  status();
 },480);
 return sync;
}
function photoCompress(file){return new Promise((resolve,reject)=>{if(!file) return resolve(null);if(!['image/jpeg','image/png','image/webp'].includes(file.type))return reject(Error('Somente JPG, PNG ou WebP.'));if(file.size>8*1024*1024)return reject(Error('Imagem maior que 8 MB.'));const url=URL.createObjectURL(file);const img=new Image();img.onerror=()=>{URL.revokeObjectURL(url);reject(Error('Não foi possível abrir a imagem.'))};img.onload=()=>{URL.revokeObjectURL(url);try{const ratio=Math.min(1,320/img.width,390/img.height),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*ratio));canvas.height=Math.max(1,Math.round(img.height*ratio));const ctx=canvas.getContext('2d');ctx.fillStyle='#151519';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);let data=canvas.toDataURL('image/jpeg',.72);if(data.length>149000)data=canvas.toDataURL('image/jpeg',.48);if(data.length>149000)throw Error('Imagem ainda é grande demais.');resolve(data)}catch(e){reject(e)}};img.src=url})}

document.addEventListener('click',async e=>{
 if(e.target.id==='modal-backdrop'){state.modal=null;render();return}
 const btn=e.target.closest('[data-action]');if(!btn||btn.disabled)return;const act=btn.dataset.action,val=btn.dataset.value,id=btn.dataset.id;
 try{
 if(act.startsWith('mesa-')){btn.disabled=true;await window.SLASHER71.action(act,btn,{state,api,refreshCampaign,render,toast});return}
 switch(act){
 case 'demo-enter':state.user=api.me;await loadLobby();return;
 case 'demo-reset':{if(!confirm('Apagar os dados locais da demonstração e restaurar fichas?'))return;try{localStorage.removeItem(NOCACHE)}catch{};await api.init();state.user=null;render();return}
 case 'auth-tab':state.authTab=val;render();return;
 case 'logout':if(state.mode==='online'&&state.user?.is_anonymous&&!confirm('Esta conta está vinculada ao navegador. Sair pode fazer você perder acesso às fichas. Continuar?'))return;await api.logout();state.user=null;state.campaign=null;state.campaignId=null;state.page='lobby';api.unsubscribe?.();render();return;
 case 'switch-role':{state.gmPreview=!state.gmPreview;state.user=state.gmPreview?{id:'demo-player',email:'jogador@dunmoore.demo'}:{id:'demo-gm',email:'mestre@dunmoore.demo'};api.me=state.user;if(state.page==='gm'&&state.gmPreview)state.page='sheet';render();return}
 case 'go':if(val==='gm'&&!isGM())throw Error('Apenas o mestre pode usar este painel');state.page=val;state.modal=null;render();return;
 case 'open-campaign':await openCampaign(id);return;
 case 'modal':if(val==='grant'&&!isGM())throw Error('Somente o mestre pode conceder itens');if(val==='edit-character'&&!canEdit(state.characters.find(c=>c.id===id)))throw Error('Ficha protegida');state.modal={type:val,id,kind:btn.dataset.kind,portraitData:null};render();return;
 case 'close-modal':state.modal=null;render();return;
 case 'select-char':state.selected=id;state.page='sheet';render();return;
 case 'random-npc':await randomNpc();return;
 case 'random-fields':{const form=$('#create-character');if(!form)return;const a=randomChar();form.elements.name.value=a.name;form.elements.age.value=a.age;form.elements.class_key.value=a.class_key;form.elements.occupation.value=a.occupation;$('#class-preview').innerHTML=classSummary(a.class_key);return}
 case 'copy-invite':await copyText(state.campaign.invite_code);return;
 case 'clear-portrait':{if(!state.modal)return;state.modal.portraitData='';const el=$('#portrait-preview');if(el)el.innerHTML='<div class="avatar">?</div>';const file=$('#portrait-file');if(file)file.value='';return}
 case 'stat':{if(!isGM())throw Error('Somente o mestre pode alterar indicadores');btn.disabled=true;await syncAction(()=>api.changeStat(id,btn.dataset.stat,Number(btn.dataset.delta)));return}
 case 'set-clock':{if(!isGM())throw Error('Somente o mestre controla os relógios');const key=btn.dataset.key;let newValue=Number(val);if(state.campaign[key]===newValue)newValue=Math.max(0,newValue-1);btn.disabled=true;await syncAction(()=>api.setClock(key,newValue),'Relógio da cidade atualizado.');return}
 case 'save-gm-note':{if(!isGM())throw Error('Sem acesso');const v=$('#gm-note').value;btn.disabled=true;await syncAction(()=>api.saveNote(v),'Nota secreta salva.');return}
 case 'remove-effect':{if(!isGM())throw Error('Somente o mestre remove recursos');if(!confirm('Remover este recurso da ficha?'))return;btn.disabled=true;await syncAction(()=>api.removeEffect(id),'Recurso removido da ficha.');return}
 case 'close-dice':$('#dice-overlay')?.remove();return;
 }
 }catch(err){console.error(err);toast('Erro: '+safeErr(err));btn.disabled=false}
});
document.addEventListener('change',async e=>{
 if(e.target.id==='sheet-picker'||e.target.id==='gm-picker'){state.selected=e.target.value;render();return}
 if(e.target.id==='class-picker'){$('#class-preview').innerHTML=classSummary(e.target.value);return}
 if(e.target.id==='m71-focus'){window.SLASHER71.focusChanged(state,e.target.value);render();return}
 if(e.target.id==='portrait-file'){
  try{const data=await photoCompress(e.target.files[0]);if(!state.modal||state.modal.type!=='edit-character')return;state.modal.portraitData=data;$('#portrait-preview').innerHTML=`<div class="avatar"><img alt="Prévia do retrato" src="${esc(data)}"></div>`;toast('Retrato preparado. Clique em salvar ficha para sincronizar.')}catch(err){toast(safeErr(err));e.target.value=''}
 }
});

document.addEventListener('submit',async e=>{
 e.preventDefault();const form=e.target;const formId=form.getAttribute('id');if(!formId&&!form.dataset.mesaForm)return;const dat=Object.fromEntries(new FormData(form).entries());const submit=form.querySelector('button[type=submit]');if(submit?.disabled)return;if(submit)submit.disabled=true;
 try{
 if(form.dataset.mesaForm){await window.SLASHER71.submit(form,{state,api,refreshCampaign,render,toast},e.submitter);return}
 if(formId==='quick-auth-form'){
  if(state.mode!=='online')throw Error('Acesso rápido indisponível na demonstração');const result=await api.anonymousAuth(dat.nickname);state.user=result.user;await loadLobby();toast('Acesso criado como '+dat.nickname);return;
 }
 if(formId==='auth-form'){
 const result=await api.auth(state.authTab,dat.email,dat.password);if(result.session){state.user=result.user;await loadLobby()}else{state.authTab='login';render();toast('Cadastro recebido. Confira seu e-mail para confirmar a conta.')}return;
 }
 if(formId==='create-campaign'){const id=await api.createCampaign(dat.name,dat.nick);state.modal=null;await openCampaign(id);toast('Campanha criada. Compartilhe o código de convite.');return}
 if(formId==='join-campaign'){const id=await api.joinCampaign(dat.code,dat.nick);state.modal=null;await openCampaign(id);toast('Você entrou na campanha.');return}
 if(formId==='create-character'){
 const id=await api.createCharacter({campaign_id:state.campaignId,name:dat.name.trim(),class_key:dat.class_key,age:Number(dat.age),occupation:dat.occupation?.trim()||'',npc:!!dat.npc&&isGM()});state.selected=id;state.modal=null;state.page='sheet';await refreshCampaign(true);toast('Sobrevivente adicionado ao arquivo.');return;
 }
 if(formId==='grant-effect'){if(!isGM())throw Error('Apenas o mestre pode conceder recursos');await api.grantEffect(dat.character_id,dat.kind,dat.title.trim(),dat.details.trim());state.modal=null;await refreshCampaign(true);toast('Recurso concedido e sincronizado.');return}
 if(formId==='assign-character'){if(!isGM())throw Error('Apenas o mestre atribui fichas');await api.assignCharacter(dat.id,dat.owner_id||null);state.modal=null;await refreshCampaign(true);toast('Responsável pela ficha atualizado.');return}
 if(formId==='edit-character'){
 const ch=state.characters.find(c=>c.id===dat.id);if(!canEdit(ch))throw Error('Você não pode editar esta ficha');const portrait=state.modal?.portraitData??ch.portrait;
 await api.updateCharacter({id:ch.id,name:dat.name.trim(),notes:dat.notes,portrait});state.modal=null;await refreshCampaign(true);toast('Ficha e retrato salvos.');return;
 }
 if(formId==='dice-form'){
 const kind=dat.kind;if(kind==='monster'&&!isGM())throw Error('Somente o mestre pode rolar por monstros');const char=state.characters.find(c=>c.id===dat.character_id);if(char&&!canEdit(char))throw Error('Esta ficha não pertence a você');const modifier=(kind==='monster'||dat.attribute==='none'?0:Number(char?.attrs[dat.attribute]||0))+Number(dat.circumstance);
 const p={campaign_id:state.campaignId,character_id:kind==='monster'?null:dat.character_id||null,kind,description:String(dat.description||'').trim()||rollDescription(kind,dat.attribute,char?.name),modifier,damage_sides:kind==='test'?0:Number(dat.damage_sides)};
 await executeRoll(p);return;
 }
 }catch(err){console.error(err);toast('Erro: '+safeErr(err))}finally{if(submit?.isConnected)submit.disabled=false}
});

document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('#dice-overlay')){$('#dice-overlay').remove();return}if(state.modal){state.modal=null;render()}}});
window.addEventListener('storage',e=>{if(state.mode==='demo'&&e.key===NOCACHE&&state.user){try{api.data=JSON.parse(e.newValue);if(state.campaignId)refreshCampaign(false);else loadLobby()}catch{}}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state.campaignId&&state.mode==='online')refreshCampaign(false).catch(console.error)});
setInterval(()=>{if(!document.hidden&&state.campaignId&&state.mode==='online')refreshCampaign(false).catch(console.error)},20000);
(async()=>{try{const user=await api.init();state.user=state.mode==='demo'?null:user;if(user&&state.mode==='online')await loadLobby();else render()}catch(e){console.error(e);$('#app').innerHTML=`<div class="login-side" style="min-height:100vh"><div class="panel"><h2>Falha de conexão</h2><p>${esc(safeErr(e))}</p><p class="hint">Verifique config.js, o banco e a conexão com a internet.</p><button class="btn red" onclick="location.reload()">Tentar novamente</button></div></div>`}})();